<?php

namespace App\Services\AmdRent;

use Illuminate\Http\Request;
use Illuminate\Support\Str;

class PublicBookingNavigation
{
    // Targets are generated by our controllers and kept in this browser's session.
    // The login URL never accepts an arbitrary redirect supplied by the client.
    public function loginUrl(Request $request, string $target): string
    {
        $token = (string) Str::uuid();
        $targets = array_filter($request->session()->get('public_booking_resumes', []),
            fn ($entry) => $entry['expires_at'] > now()->timestamp);
        $targets[$token] = ['url' => $target, 'expires_at' => now()->addHours(2)->timestamp];
        $request->session()->put('public_booking_resumes', array_slice($targets, -20, null, true));

        return route('public-account.login', ['resume' => $token]);
    }

    public function remember(Request $request): void
    {
        if (!$request->has('resume')) return;
        $request->session()->forget('public_booking_resume');
        $token = $request->query('resume');
        if ($this->target($request, $token)) $request->session()->put('public_booking_resume', $token);
    }

    public function consume(Request $request): ?string
    {
        $token = $request->session()->pull('public_booking_resume');
        $target = $this->target($request, $token);
        if (is_string($token) && Str::isUuid($token)) $request->session()->forget('public_booking_resumes.'.$token);

        return $target;
    }

    private function target(Request $request, mixed $token): ?string
    {
        if (!is_string($token) || !Str::isUuid($token)) return null;
        $entry = $request->session()->get('public_booking_resumes.'.$token);

        return is_array($entry) && $entry['expires_at'] > now()->timestamp ? $entry['url'] : null;
    }
}
